def label(status):
    if 200 <= status < 300:
        return "ok"
    if status >= 500:
        return "server error"
    return "other"

def first_large(values):
    for value in values:
        if value > 10:
            return value
    return None

print(first_large([2, 15, 20]))

def add_label(label, labels=None):
    if labels is None:
        labels = []
    return labels + [label]

print(add_label("a"), add_label("b"))

from pathlib import PurePosixPath

def report_name(path):
    return PurePosixPath(path).name

if __name__ == "__main__":
    print(report_name("/tmp/report.csv"))

def broken(values):
    total = 0
    for value in values:
        total += value
        return total

print(broken([2, 5]))

